input.command:
python3 - <<'EOF'
s=open('index.html').read()
s=s.replace("p.week >= 27 ? p.week - p.nWeeks - 1 : p.week - 1","p.week >= 40 ? p.week - p.nWeeks - 1 : p.week - 1")
s=s.replace("w >= 27 ? w - 53 : w - 1","w >= 40 ? w - 53 : w - 1")
s=s.replace("d3.scaleLinear().domain([-13, 39])","d3.scaleLinear().domain([-14, 39])")
s=s.replace("const R = 345, r0 = 30;\n  const cx = 375, cy = 385;","const R = 335, r0 = 30;\n  const cx = 375, cy = 400;")
old_start=s.index("  // Caption computed from data")
old_end=s.index("  // ---------- colours")
new='''  // Caption computed from data: offset of peak relative to week 1 (weeks 40..53 -> negative)
  const off = p => p.week >= 40 ? p.week - p.nWeeks - 1 : p.week - 1;
  const pre = completePeaks.filter(p => +p.season.slice(0, 4) < 2020);
  const post = completePeaks.filter(p => +p.season.slice(0, 4) >= 2020);
  const wlab = o => "W" + (o < 0 ? o + 53 : o + 1);
  const ext = arr => d3.extent(arr, off);
  const [a0, a1] = ext(pre), [b0, b1] = ext(post);
  d3.select("#caption").text(
    `Not any more: from ${pre[0].season} to ${pre[pre.length - 1].season} the season peak always fell in ISO weeks ${wlab(a0)}–${wlab(a1)} (February–March), ` +
    `but from ${post[0].season} on it has ranged from ${wlab(b0)} to ${wlab(b1)}, with recent peaks in December or January.`);

'''
s=s[:old_start]+new+s[old_end:]
open('index.html','w').write(s)
EOF
render index.html

